        for dep in tasks[curr]["depends_on"]:
            if dep not in tasks:
                unresolved.add(dep)
            if dep not in visited:
                queue.append(dep)
    else:
        unresolved.add(curr)

in_degree = {v: 0 for v in visited}
adj = defaultdict(list)
edges = []

for u in sorted(visited):
    for v in sorted(tasks.get(u, {}).get("depends_on", [])):
        if v in visited:
            edges.append(f"{u} -> {v}")
            adj[v].append(u)
            in_degree[u] += 1

heap = [v for v in visited if in_degree[v] == 0]
heapq.heapify(heap)
topo = []
while heap:
    c = heapq.heappop(heap)
    topo.append(c)
    for n in sorted(adj[c]):
        in_degree[n] -= 1
        if in_degree[n] == 0:
            heapq.heappush(heap, n)

vdfs = {}
has_cycle = False
def dfs(u):
